args.content:
PREFIX dbp: <http://dbpedia.org/ontology/>
PREFIX geo: <http://www.georss.org/georss/>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?item ?label ?latitude ?longitude
WHERE {
  ?item a dbp:PointOfInterest .
  ?item dbp:label ?label .
  ?item dbp:latitude ?latitude .
  ?item dbp:longitude ?longitude .

  FILTER(?item IN {
    SELECT ?item WHERE {
      ?item a dbpedia:City .
      FILTER(?item = Q8813)
    }
  })
}

